23	
24	/// Execution mode of the command
25	#[derive(Debug, Clone, Copy, PartialEq)]
26	pub enum ExecutionMode {
27	    /// Command is executed for each search result
28	    OneByOne,
29	    /// Command is run for a batch of results at once
30	    Batch,
31	}
32	
33	/// Represents a template that is utilized to generate command strings.
34	///
35	/// The template is meant to be coupled with an input in order to generate a command. The
36	/// `generate_and_execute()` method will be used to generate a command and execute it.
37	#[derive(Debug, Clone, PartialEq)]
38	pub struct CommandTemplate {
39	    args: Vec<ArgumentTemplate>,
40	    mode: ExecutionMode,
41	    path_separator: Option<String>,
42	}
43	
44	impl CommandTemplate {
45	    pub fn new<I, S>(input: I, path_separator: Option<String>) -> CommandTemplate
46	    where
47	        I: IntoIterator<Item = S>,
48	        S: AsRef<str>,
49	    {
50	        Self::build(input, ExecutionMode::OneByOne, path_separator)
51	    }
52	
53	    pub fn new_batch<I, S>(input: I, path_separator: Option<String>) -> Result<CommandTemplate>
54	    where
55	        I: IntoIterator<Item = S>,
56	        S: AsRef<str>,
57	    {
58	        let cmd = Self::build(input, ExecutionMode::Batch, path_separator);
59	        if cmd.number_of_tokens() > 1 {
60	            return Err(anyhow!("Only one placeholder allowed for batch commands"));
61	        }
62	        if cmd.args[0].has_tokens() {
63	            return Err(anyhow!(
64	                "First argument of exec-batch is expected to be a fixed executable"
65	            ));
66	        }
67	        Ok(cmd)
68	    }
69	
70	    fn build<I, S>(input: I, mode: ExecutionMode, path_separator: Option<String>) -> CommandTemplate
71	    where
72	        I: IntoIterator<Item = S>,
73	        S: AsRef<str>,
74	    {
75	        lazy_static! {
76	            static ref PLACEHOLDER_PATTERN: Regex = Regex::new(r"\{(/?\.?|//)\}").unwrap();
77	        }
78	
79	        let mut args = Vec::new();
80	        let mut has_placeholder = false;
81	
82	        for arg in input {
83	            let arg = arg.as_ref();
84	
85	            let mut tokens = Vec::new();
86	            let mut start = 0;
87	
88	            for placeholder in PLACEHOLDER_PATTERN.find_iter(arg) {
89	                // Leading text before the placeholder.
90	                if placeholder.start() > start {
91	                    tokens.push(Token::Text(arg[start..placeholder.start()].to_owned()));
92	                }
93	
94	                start = placeholder.end();
95	
96	                match placeholder.as_str() {
97	                    "{}" => tokens.push(Token::Placeholder),
98	                    "{.}" => tokens.push(Token::NoExt),
99	                    "{/}" => tokens.push(Token::Basename),
100	                    "{//}" => tokens.push(Token::Parent),
101	                    "{/.}" => tokens.push(Token::BasenameNoExt),
102	                    _ => unreachable!("Unhandled placeholder"),
103	                }
104	
105	                has_placeholder = true;
106	            }
107	
108	            // Without a placeholder, the argument is just fixed text.
109	            if tokens.is_empty() {
110	                args.push(ArgumentTemplate::Text(arg.to_owned()));
111	                continue;
112	            }
113	
114	            if start < arg.len() {
115	                // Trailing text after last placeholder.
116	                tokens.push(Token::Text(arg[start..].to_owned()));
117	            }
118	
119	            args.push(ArgumentTemplate::Tokens(tokens));
120	        }
121	
122	        // If a placeholder token was not supplied, append one at the end of the command.
123	        if !has_placeholder {
124	            args.push(ArgumentTemplate::Tokens(vec![Token::Placeholder]));
125	        }
126	
127	        CommandTemplate {
128	            args,
129	            mode,
130	            path_separator,
131	        }
132	    }
133	
134	    fn number_of_tokens(&self) -> usize {
135	        self.args.iter().filter(|arg| arg.has_tokens()).count()
136	    }
137	
138	    /// Generates and executes a command.
139	    ///
140	    /// Using the internal `args` field, and a supplied `input` variable, a `Command` will be
141	    /// build. Once all arguments have been processed, the command is executed.
142	    pub fn generate_and_execute(
143	        &self,
144	        input: &Path,
145	        out_perm: Arc<Mutex<()>>,
146	        buffer_output: bool,
147	    ) -> ExitCode {
148	        let input = strip_current_dir(input);
149	
150	        let mut cmd = Command::new(self.args[0].generate(&input, self.path_separator.as_deref()));
151	        for arg in &self.args[1..] {
152	            cmd.arg(arg.generate(&input, self.path_separator.as_deref()));
153	        }
154	
155	        execute_command(cmd, &out_perm, buffer_output)
156	    }
157	
158	    pub fn in_batch_mode(&self) -> bool {
159	        self.mode == ExecutionMode::Batch
160	    }
161	
162	    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
163	    where
164	        I: Iterator<Item = PathBuf>,
165	    {
166	        let mut cmd = Command::new(self.args[0].generate("", None));
167	        cmd.stdin(Stdio::inherit());
168	        cmd.stdout(Stdio::inherit());
169	        cmd.stderr(Stdio::inherit());
170	
171	        let mut paths: Vec<_> = paths.collect();
172	        let mut has_path = false;
173	
174	        for arg in &self.args[1..] {
175	            if arg.has_tokens() {
176	                paths.sort();
177	
178	                // A single `Tokens` is expected
179	                // So we can directly consume the iterator once and for all
180	                for path in &mut paths {
181	                    cmd.arg(arg.generate(strip_current_dir(path), self.path_separator.as_deref()));
182	                    has_path = true;
183	                }
184	            } else {
185	                cmd.arg(arg.generate("", None));
186	            }
187	        }
188	
189	        if has_path {
190	            execute_command(cmd, &Mutex::new(()), buffer_output)
191	        } else {
192	            ExitCode::Success
193	        }
194	    }
195	}
196	
197	/// Represents a template for a single command argument.
198	///
199	/// The argument is either a collection of `Token`s including at least one placeholder variant, or
200	/// a fixed text.
201	#[derive(Clone, Debug, PartialEq)]
202	enum ArgumentTemplate {
203	    Tokens(Vec<Token>),
204	    Text(String),
205	}
206	
207	impl ArgumentTemplate {
208	    pub fn has_tokens(&self) -> bool {
209	        matches!(self, ArgumentTemplate::Tokens(_))
210	    }
211	
212	    /// Generate an argument from this template. If path_separator is Some, then it will replace
213	    /// the path separator in all placeholder tokens. Text arguments and tokens are not affected by
214	    /// path separator substitution.
215	    pub fn generate(&self, path: impl AsRef<Path>, path_separator: Option<&str>) -> OsString {
216	        use self::Token::*;
217	        let path = path.as_ref();
218	
219	        match *self {
220	            ArgumentTemplate::Tokens(ref tokens) => {
221	                let mut s = OsString::new();
222	                for token in tokens {
223	                    match *token {
224	                        Basename => s.push(Self::replace_separator(basename(path), path_separator)),
225	                        BasenameNoExt => s.push(Self::replace_separator(
226	                            &remove_extension(basename(path).as_ref()),
227	                            path_separator,
228	                        )),
229	                        NoExt => s.push(Self::replace_separator(
230	                            &remove_extension(path),
231	                            path_separator,
232	                        )),
233	                        Parent => s.push(Self::replace_separator(&dirname(path), path_separator)),
234	                        Placeholder => {
235	                            s.push(Self::replace_separator(path.as_ref(), path_separator))
236	                        }
237	                        Text(ref string) => s.push(string),
238	                    }
239	                }
240	                s
241	            }
242	            ArgumentTemplate::Text(ref text) => OsString::from(text),
243	        }
244	    }
245	
246	    /// Replace the path separator in the input with the custom separator string. If path_separator
247	    /// is None, simply return a borrowed Cow<OsStr> of the input. Otherwise, the input is
248	    /// interpreted as a Path and its components are iterated through and re-joined into a new
249	    /// OsString.
250	    fn replace_separator<'a>(path: &'a OsStr, path_separator: Option<&str>) -> Cow<'a, OsStr> {
251	        // fast-path - no replacement necessary
252	        if path_separator.is_none() {
253	            return Cow::Borrowed(path);
254	        }
255	
256	        let path_separator = path_separator.unwrap();
257	        let mut out = OsString::with_capacity(path.len());
258	        let mut components = Path::new(path).components().peekable();
259	
260	        while let Some(comp) = components.next() {
261	            match comp {
262	                // Absolute paths on Windows are tricky.  A Prefix component is usually a drive
263	                // letter or UNC path, and is usually followed by RootDir. There are also
264	                // "verbatim" prefixes beginning with "\\?\" that skip normalization. We choose to
265	                // ignore verbatim path prefixes here because they're very rare, might be
266	                // impossible to reach here, and there's no good way to deal with them. If users
267	                // are doing something advanced involving verbatim windows paths, they can do their
268	                // own output filtering with a tool like sed.
269	                Component::Prefix(prefix) => {
270	                    if let Prefix::UNC(server, share) = prefix.kind() {
271	                        // Prefix::UNC is a parsed version of '\\server\share'
272	                        out.push(path_separator);
273	                        out.push(path_separator);
274	                        out.push(server);
275	                        out.push(path_separator);
276	                        out.push(share);
277	                    } else {
278	                        // All other Windows prefix types are rendered as-is. This results in e.g. "C:" for
279	                        // drive letters. DeviceNS and Verbatim* prefixes won't have backslashes converted,
280	                        // but they're not returned by directories fd can search anyway so we don't worry
281	                        // about them.
282	                        out.push(comp.as_os_str());
283	                    }
284	                }
285	
286	                // Root directory is always replaced with the custom separator.
287	                Component::RootDir => out.push(path_separator),
288	
289	                // Everything else is joined normally, with a trailing separator if we're not last
290	                _ => {
291	                    out.push(comp.as_os_str());
292	                    if components.peek().is_some() {
293	                        out.push(path_separator);
294	                    }
295	                }
296	            }
297	        }
298	        Cow::Owned(out)
299	    }
300	}
