use std::path::{Component, Path, PathBuf, Prefix};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};

use anyhow::{anyhow, Result};
use lazy_static::lazy_static;
use regex::Regex;

use crate::exit_codes::{merge_exitcodes, ExitCode};
use crate::filesystem::strip_current_dir;

use self::command::execute_command;
use self::input::{basename, dirname, remove_extension};
pub use self::job::{batch, job};
use self::token::Token;

/// Execution mode of the command
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ExecutionMode {
    /// Command is executed for each search result
    OneByOne,
    /// Command is run for a batch of results at once
    Batch,
}

/// Represents a template that is utilized to generate command strings.
///
/// The template is meant to be coupled with an input in order to generate a command. The
/// `generate_and_execute()` method will be used to generate a command and execute it.
#[derive(Debug, Clone, PartialEq)]
pub struct CommandTemplate {
    args: Vec<ArgumentTemplate>,
    mode: ExecutionMode,
    path_separator: Option<String>,
}

impl CommandTemplate {
    pub fn new<I, S>(input: I, path_separator: Option<String>) -> CommandTemplate
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        Self::build(input, ExecutionMode::OneByOne, path_separator)
    }

    pub fn new_batch<I, S>(input: I, path_separator: Option<String>) -> Result<CommandTemplate>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let cmd = Self::build(input, ExecutionMode::Batch, path_separator);
        if cmd.number_of_tokens() > 1 {
            return Err(anyhow!("Only one placeholder allowed for batch commands"));
        }
        if cmd.args[0].has_tokens() {
            return Err(anyhow!(
                "First argument of exec-batch is expected to be a fixed executable"
            ));
        }
        Ok(cmd)
    }

    fn build<I, S>(input: I, mode: ExecutionMode, path_separator: Option<String>) -> CommandTemplate
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        lazy_static! {
            static ref PLACEHOLDER_PATTERN: Regex = Regex::new(r"\{(/?\.?|//)\}").unwrap();
        }

        let mut args = Vec::new();
        let mut has_placeholder = false;

        for arg in input {
            let arg = arg.as_ref();

            let mut tokens = Vec::new();
            let mut start = 0;

            for placeholder in PLACEHOLDER_PATTERN.find_iter(arg) {
                // Leading text before the placeholder.
                if placeholder.start() > start {
                    tokens.push(Token::Text(arg[start..placeholder.start()].to_owned()));
                }

                start = placeholder.end();

                match placeholder.as_str() {
                    "{}" => tokens.push(Token::Placeholder),
                    "{.}" => tokens.push(Token::NoExt),
                    "{/}" => tokens.push(Token::Basename),
                    "{//}" => tokens.push(Token::Parent),
                    "{/.}" => tokens.push(Token::BasenameNoExt),
                    _ => unreachable!("Unhandled placeholder"),
                }

                has_placeholder = true;
            }

            // Without a placeholder, the argument is just fixed text.
            if tokens.is_empty() {
                args.push(ArgumentTemplate::Text(arg.to_owned()));
                continue;
            }

            if start < arg.len() {
                // Trailing text after last placeholder.
                tokens.push(Token::Text(arg[start..].to_owned()));
            }

            args.push(ArgumentTemplate::Tokens(tokens));
        }

        // If a placeholder token was not supplied, append one at the end of the command.
        if !has_placeholder {
            args.push(ArgumentTemplate::Tokens(vec![Token::Placeholder]));
        }

        CommandTemplate {
            args,
            mode,
            path_separator,
        }
    }

    fn number_of_tokens(&self) -> usize {
        self.args.iter().filter(|arg| arg.has_tokens()).count()
    }

    /// Generates and executes a command.
    ///
    /// Using the internal `args` field, and a supplied `input` variable, a `Command` will be
    /// build. Once all arguments have been processed, the command is executed.
    pub fn generate_and_execute(
        &self,
        input: &Path,
        out_perm: Arc<Mutex<()>>,
        buffer_output: bool,
    ) -> ExitCode {
        let input = strip_current_dir(input);

        let mut cmd = Command::new(self.args[0].generate(&input, self.path_separator.as_deref()));
        for arg in &self.args[1..] {
            cmd.arg(arg.generate(&input, self.path_separator.as_deref()));
        }

        execute_command(cmd, &out_perm, buffer_output)
    }

    pub fn in_batch_mode(&self) -> bool {
        self.mode == ExecutionMode::Batch
    }

    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        if paths.is_empty() {
            return ExitCode::Success;
        }
        paths.sort();

        // Position of the (single) argument that contains the placeholder(s).
        let path_arg_index = match self.args[1..].iter().position(ArgumentTemplate::has_tokens) {
            Some(index) => index,
            None => return ExitCode::Success,
        };

        // On top of each argument's string contents (plus a terminating NUL byte), the kernel
        // also has to store a pointer to it in the argv array.
        let pointer_size = std::mem::size_of::<*const u8>();

        // Fixed overhead of the command that stays the same across all batches: the executable
        // name and all of the other, non-placeholder arguments.
        let fixed_len = self.args[0].generate("", None).len()
            + pointer_size
            + self.args[1..]
                .iter()
                .enumerate()
                .filter(|&(index, _)| index != path_arg_index)
                .map(|(_, arg)| arg.generate("", None).len() + 1 + pointer_size)
                .sum::<usize>();

        let max_len = max_command_line_length();

        let mut results = Vec::new();
        let mut batch: Vec<OsString> = Vec::new();
        let mut batch_len = fixed_len;

        for path in &paths {
            let generated = self.args[1 + path_arg_index]
                .generate(strip_current_dir(path), self.path_separator.as_deref());
            let generated_len = generated.len() + 1 + pointer_size;

            if !batch.is_empty() && batch_len + generated_len > max_len {
                results.push(self.execute_batch(&batch, path_arg_index, buffer_output));
                batch.clear();
                batch_len = fixed_len;
            }

            batch_len += generated_len;
            batch.push(generated);
        }

        if !batch.is_empty() {
            results.push(self.execute_batch(&batch, path_arg_index, buffer_output));
        }

        merge_exitcodes(results)
    }

    /// Executes a single batch of the command, substituting `batch_args` for the placeholder
    /// argument at `path_arg_index`.
    fn execute_batch(
        &self,
        batch_args: &[OsString],
        path_arg_index: usize,
        buffer_output: bool,
    ) -> ExitCode {
        let mut cmd = Command::new(self.args[0].generate("", None));
        cmd.stdin(Stdio::inherit());
        cmd.stdout(Stdio::inherit());
        cmd.stderr(Stdio::inherit());

        for (index, arg) in self.args[1..].iter().enumerate() {
            if index == path_arg_index {
                cmd.args(batch_args);
            } else {
                cmd.arg(arg.generate("", None));
            }
        }

        execute_command(cmd, &Mutex::new(()), buffer_output)
    }
}

/// The maximum length (in bytes) of the argument/environment vector that is passed to a new
/// process. Batches of paths are split up in order to stay below this threshold, similar to what
/// `xargs` does.
#[cfg(all(unix, not(target_os = "redox")))]
fn max_command_line_length() -> usize {
    static DEFAULT: usize = 128 * 1024;
    // Reserve some headroom for the environment and other overhead that the OS also has to fit
    // into the same limit.
    static RESERVED: usize = 4 * 1024;

    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    if arg_max <= 0 {
        return DEFAULT;
    }

    (arg_max as usize).saturating_sub(RESERVED).max(RESERVED)
}

